/** Expand a brace pattern into its ordered list of expansions (duplicates kept). */
export function braceExpand(pattern) {
  return expandArr(pattern)
}

function expandArr(s) {
  const group = findGroup(s)
  if (!group) return [s]
  const { start, end, alternatives } = group
  const arr = Array.from(s)
  const prefix = arr.slice(0, start).join('')
  const suffix = arr.slice(end + 1).join('')
  const results = []
  for (const alt of alternatives) {
    results.push(...expandArr(prefix + alt + suffix))
  }
  return results
}

function findGroup(s) {
  const arr = Array.from(s)
  let i = 0
  while (i < arr.length) {
    if (arr[i] === '\\') {
      i += 2
      continue
    }
    if (arr[i] === '{') {
      const close = findMatchingBrace(arr, i)
      if (close === -1) {
        i += 1
        continue
      }
      const body = arr.slice(i + 1, close).join('')
      const alternatives = computeAlternatives(body)
      if (alternatives === null) {
        i += 1
        continue
      }
      return { start: i, end: close, alternatives }
    }
    i += 1
  }
  return null
}

function findMatchingBrace(arr, openIdx) {
  let depth = 1
  let j = openIdx + 1
  while (j < arr.length) {
    if (arr[j] === '\\') {
      j += 2
      continue
    }
    if (arr[j] === '{') {
      depth += 1
      j += 1
      continue
    }
    if (arr[j] === '}') {
      depth -= 1
      if (depth === 0) return j
      j += 1
      continue
    }
    j += 1
  }
  return -1
}

function computeAlternatives(body) {
  const parts = splitTopCommas(body)
  if (parts.length > 1) return parts
  return tryRange(body)
}

function splitTopCommas(body) {
  const arr = Array.from(body)
  const parts = []
  let depth = 0
  let cur = []
  let i = 0
  while (i < arr.length) {
    const c = arr[i]
    if (c === '\\') {
      cur.push(c)
      if (i + 1 < arr.length) cur.push(arr[i + 1])
      i += 2
      continue
    }
    if (c === '{') {
      depth += 1
      cur.push(c)
      i += 1
      continue
    }
    if (c === '}') {
      depth -= 1
      cur.push(c)
      i += 1
      continue
    }
    if (c === ',' && depth === 0) {
      parts.push(cur.join(''))
      cur = []
      i += 1
      continue
    }
    cur.push(c)
    i += 1
  }
  parts.push(cur.join(''))
  return parts
}

const INT_RANGE = /^([+-]?\d+)\.\.([+-]?\d+)(?:\.\.([+-]?\d+))?$/
const CHAR_RANGE = /^([A-Za-z])\.\.([A-Za-z])(?:\.\.([+-]?\d+))?$/

function tryRange(body) {
  let m = INT_RANGE.exec(body)
  if (m) {
    const [, aStr, bStr, sStr] = m
    const step = sStr === undefined ? 1 : Math.abs(parseInt(sStr, 10))
    if (step === 0) return null
    return buildIntRange(aStr, bStr, step)
  }
  m = CHAR_RANGE.exec(body)
  if (m) {
    const [, aCh, bCh, sStr] = m
    const step = sStr === undefined ? 1 : Math.abs(parseInt(sStr, 10))
    if (step === 0) return null
    return buildCharRange(aCh, bCh, step)
  }
  return null
}

function digitsInfo(str) {
  const sign = str[0] === '+' || str[0] === '-' ? str[0] : ''
  const digits = sign ? str.slice(1) : str
  return { sign, digits, value: parseInt(str, 10) }
}

function hasLeadingZero(info) {
  return info.digits.length > 1 && info.digits[0] === '0'
}

function buildIntRange(aStr, bStr, step) {
  const a = digitsInfo(aStr)
  const b = digitsInfo(bStr)
  const pad = hasLeadingZero(a) || hasLeadingZero(b)
  const width = Math.max(a.digits.length, b.digits.length)
  const dir = a.value <= b.value ? 1 : -1
  const count = Math.floor(Math.abs(b.value - a.value) / step) + 1
  if (count > 1000) throw new CliError('range is too long')
  const results = []
  let v = a.value
  for (let i = 0; i < count; i += 1) {
    results.push(formatInt(v, pad, width))
    v += dir * step
  }
  return results
}

function formatInt(v, pad, width) {
  if (!pad) return String(v)
  const sign = v < 0 ? '-' : ''
  const digits = String(Math.abs(v)).padStart(width, '0')
  return sign + digits
}

function buildCharRange(aCh, bCh, step) {
  const a = aCh.codePointAt(0)
  const b = bCh.codePointAt(0)
  const dir = a <= b ? 1 : -1
  const count = Math.floor(Math.abs(b - a) / step) + 1
  if (count > 1000) throw new CliError('range is too long')
  const results = []
  let v = a
  for (let i = 0; i < count; i += 1) {
    results.push(String.fromCodePoint(v))
    v += dir * step
  }
  return results
}
"}

