{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js expand` prints the brace expansions of the one
 * pattern on standard input; `node src/cli.js match` reads a pattern and then
 * one candidate path per line, and verdicts each candidate.
 */
import { readFileSync } from 'node:fs'
import { braceExpand } from './brace.js'
import { compileMatcher } from './match.js'
import { CliError } from './errors.js'

function fail(msg) {
  process.stderr.write(`error: ${msg}\n`)
  process.exit(2)
}

function readLines() {
  let input
  try {
    input = readFileSync(0, 'utf8')
  } catch {
    input = ''
  }
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'expand' && args[0] !== 'match')) {
    fail('usage: cli.js expand|match')
  }
  const mode = args[0]
  const lines = readLines()

  if (mode === 'expand') {
    if (lines.length !== 1) fail('expand needs exactly one pattern line')
    let results
    try {
      results = braceExpand(lines[0])
    } catch (e) {
      if (e instanceof CliError) fail(e.message)
      throw e
    }
    process.stdout.write(results.map((r) => r + '\n').join(''))
    return
  }

  // match mode
  if (lines.length < 1) fail('match needs a pattern line')
  const pattern = lines[0]
  const candidates = lines.slice(1)
  let matchers
  try {
    const expansions = braceExpand(pattern)
    matchers = expansions.map(compileMatcher)
  } catch (e) {
    if (e instanceof CliError) fail(e.message)
    throw e
  }
  const out = candidates.map((c) => {
    const ok = matchers.some((m) => m(c))
    return `${ok ? '+' : '-'} ${c}`
  })
  process.stdout.write(out.map((l) => `${l}\n`).join(''))
}

main()
"}

